namespace sv_5a9364b98f7341559b3baad2e7729434.Services;

public sealed class RecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic pizza with fresh mozzarella, tomatoes, and basil.", 30),
            new(2, "Spaghetti Carbonara", "Creamy pasta with pancetta, egg yolk, and pecorino romano.", 25),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream.", 45),
        },
        [2] = new List<Recipe>
        {
            new(4, "Kung Pao Chicken", "Spicy stir-fried chicken with peanuts and vegetables.", 35),
            new(5, "Mapo Tofu", "Silken tofu in a fiery Sichuan chili bean sauce.", 20),
            new(6, "Spring Rolls", "Crispy rolls filled with seasoned vegetables and shrimp.", 40),
        },
        [3] = new List<Recipe>
        {
            new(7, "Chicken Tikka Masala", "Grilled chicken chunks in a creamy spiced tomato sauce.", 50),
            new(8, "Palak Paneer", "Fresh spinach cooked with paneer cubes and aromatic spices.", 35),
            new(9, "Biryani", "Fragrant basmati rice layered with spiced meat and herbs.", 60),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (RecipesByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return [];
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_5a9364b98f7341559b3baad2e7729434.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation
@inject ILogger<Recipes> Logger
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav class="mb-3">
    <a href="/recipes/1" class="btn btn-outline-primary me-1">Italian</a>
    <a href="/recipes/2" class="btn btn-outline-primary me-1">Chinese</a>
    <a href="/recipes/3" class="btn btn-outline-primary me-1">Indian</a>
</nav>

@if (_error is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@_error</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes...</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <div class="alert alert-info py-1 px-2 mb-2" role="status">Refreshing…</div>
    }

    @if (_recipes.Count == 0)
    {
        <p>No recipes found for this cuisine.</p>
    }
    else
    {
        <div class="mb-2">
            <label class="form-label me-2 mb-0">Sort:</label>
            <a href="@GetSortUrl("newest")" class="btn btn-sm @(_sort == "newest" ? "btn-primary" : "btn-outline-secondary") me-1">Newest</a>
            <a href="@GetSortUrl("popular")" class="btn btn-sm @(_sort == "popular" ? "btn-primary" : "btn-outline-secondary")">Popular</a>
        </div>

        <div class="row">
            @foreach (var recipe in GetSortedRecipes())
            {
                <div class="col-md-4 mb-3">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">@recipe.Description</p>
                            <span class="badge bg-secondary">@recipe.PrepTimeMinutes min</span>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery(Name = "sort")] public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _error;
    private bool _isRefreshing;
    private string _sort = "newest";

    private int _loadedCuisineId;
    private CancellationTokenSource? _loadCts;

    protected override void OnInitialized()
    {
        Navigation.LocationChanged += OnLocationChanged;
    }

    protected override void OnParametersSet()
    {
        _sort = string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase) ? "popular" : "newest";
    }

    protected override Task OnParametersSetAsync()
    {
        if (CuisineId != _loadedCuisineId)
        {
            return LoadRecipesAsync(CuisineId);
        }

        return Task.CompletedTask;
    }

    private void OnLocationChanged(object? sender, Microsoft.AspNetCore.Components.Routing.LocationChangedEventArgs e)
    {
        // OnParametersSetAsync handles cuisine changes; LocationChanged handles
        // sort-only changes that don't trigger a parameter update cycle.
    }

    private async Task LoadRecipesAsync(int cuisineId)
    {
        // Cancel any in-flight load.
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = new CancellationTokenSource();
        var ct = _loadCts.Token;

        _error = null;
        _isRefreshing = _recipes is not null;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(cuisineId, ct);

            ct.ThrowIfCancellationRequested();

            _recipes = result;
            _loadedCuisineId = cuisineId;
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // A newer load superseded this one — do nothing.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _error = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task Retry()
    {
        await LoadRecipesAsync(CuisineId);
    }

    private IEnumerable<Recipe> GetSortedRecipes()
    {
        if (_recipes is null) return [];

        return _sort == "popular"
            ? _recipes.OrderBy(r => r.PrepTimeMinutes)
            : _recipes.OrderByDescending(r => r.Id);
    }

    private string GetSortUrl(string sortValue)
    {
        return $"/recipes/{CuisineId}?sort={sortValue}";
    }

    public void Dispose()
    {
        Navigation.LocationChanged -= OnLocationChanged;
        _loadCts?.Cancel();
        _loadCts?.Dispose();
    }
}

